import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Désactiver la variable de modèle hash et ses mises à jour","description":"Découvrez comment désactiver les mises à jour de la variable hash et quand utiliser cette option de performance.","frontmatter":{"title":"Désactiver la variable de modèle hash et ses mises à jour","description":"Découvrez comment désactiver les mises à jour de la variable hash et quand utiliser cette option de performance."},"headers":[],"relativePath":"fr/projects/uix/extras/hash-template-variable-updates.md","filePath":"fr/projects/uix/extras/hash-template-variable-updates.md","lastUpdated":1795857174000}'),r={name:"fr/projects/uix/extras/hash-template-variable-updates.md"};function l(i,e,n,d,c,u){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="desactiver-la-variable-de-modele-hash-et-ses-mises-a-jour" tabindex="-1">Désactiver la variable de modèle hash et ses mises à jour <a class="header-anchor" href="#desactiver-la-variable-de-modele-hash-et-ses-mises-a-jour" aria-label="Permalink to &quot;Désactiver la variable de modèle hash et ses mises à jour&quot;">​</a></h1><p>Par défaut, UIX expose <code>hash</code> comme variable de modèle et met à jour les modèles lorsque le fragment d&#39;URL (<code>#...</code>) change. Cette option désactive ce comportement pour éviter les nouvelles liaisons et mises à jour Forge déclenchées par le hash.</p><p>UIX surveille les événements <code>location-changed</code> et <code>popstate</code> afin de réassocier les modèles lorsque le fragment change.</p><h2 id="reglage-depuis-l-interface-de-l-integration" tabindex="-1">Réglage depuis l&#39;interface de l&#39;intégration <a class="header-anchor" href="#reglage-depuis-l-interface-de-l-integration" aria-label="Permalink to &quot;Réglage depuis l&#39;interface de l&#39;intégration&quot;">​</a></h2><p>Cette option est <strong>désactivée par défaut</strong>. Pour l&#39;activer :</p><ol><li>Dans Home Assistant, ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>.</li><li>Sélectionnez <strong>Réglages de performance</strong>.</li><li>Activez <strong>Désactiver la variable de modèle hash et ses mises à jour</strong>.</li><li>Enregistrez.</li></ol><p>Le réglage prend effet immédiatement dans toutes les sessions de navigateur connectées ; aucun rechargement n&#39;est nécessaire.</p><h2 id="comportement-lorsqu-elle-est-activee" tabindex="-1">Comportement lorsqu&#39;elle est activée <a class="header-anchor" href="#comportement-lorsqu-elle-est-activee" aria-label="Permalink to &quot;Comportement lorsqu&#39;elle est activée&quot;">​</a></h2><p>Lorsque cette option est activée :</p><ul><li>La variable de modèle <code>hash</code> n&#39;est <strong>pas disponible</strong>.</li><li>Les changements d&#39;URL limités au hash ne déclenchent <strong>pas</strong> de nouvelle liaison des modèles UIX.</li><li>Les changements d&#39;URL limités au hash ne déclenchent <strong>pas</strong> de mise à jour UIX Forge.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Tout modèle qui référence <code>hash</code> sans valeur par défaut génère une erreur lorsque cette option est activée, car la variable n&#39;est plus disponible. Si vous souhaitez pouvoir activer ou désactiver l&#39;option, définissez une valeur par défaut, par exemple <code>{{ hash | default(&quot;&quot;) }}</code>, ou utilisez une variable locale dans les modèles plus complexes : <code>{% set hashWithDefault = hash | default(&quot;&quot;) %}</code>.</p></div>',11)])])}const h=a(r,[["render",l]]);export{m as __pageData,h as default};
